package in.simplifymoney.ledgersync.report;
import in.simplifymoney.ledgersync.model.*; import java.math.BigDecimal; import java.util.*;
public final class Reports { private Reports(){} private static final BigDecimal ZERO=BigDecimal.ZERO.setScale(2);
 public static Map<String,Object> summary(List<NormalizedTxn> ledger){Map<String,Object>accounts=new LinkedHashMap<>();for(String acct:new TreeSet<>(ledger.stream().map(NormalizedTxn::accountLast4).toList())){BigDecimal spend=ZERO,income=ZERO,micro=ZERO,out=ZERO,in=ZERO;int mc=0;for(NormalizedTxn t:ledger)if(t.accountLast4().equals(acct)){switch(t.category()){case SPEND->spend=spend.add(t.amount());case INCOME->income=income.add(t.amount());case MICRO->{mc++;micro=micro.add(t.amount());}case TRANSFER->{if(t.direction()==Direction.DEBIT)out=out.add(t.amount());else in=in.add(t.amount());}}}Map<String,Object>a=new LinkedHashMap<>();a.put("spend",spend.toPlainString());a.put("income",income.toPlainString());a.put("micro_count",mc);a.put("micro_total",micro.toPlainString());a.put("transferred_out",out.toPlainString());a.put("transferred_in",in.toPlainString());accounts.put(acct,a);}Map<String,Object>d=new LinkedHashMap<>();d.put("accounts",accounts);return d;}
 public static Map<String,Object> ledgerDocument(List<NormalizedTxn> ledger){List<Object>rows=ledger.stream().map(t->{Map<String,Object>r=new LinkedHashMap<>();r.put("account_last4",t.accountLast4());r.put("occurred_at",t.occurredAt().toString());r.put("direction",t.direction().name().toLowerCase());r.put("amount",t.amount().toPlainString());r.put("category",t.category().name());r.put("merchant",t.merchant());r.put("source_message_ids",t.sourceMessageIds());return(Object)r;}).toList();Map<String,Object>d=new LinkedHashMap<>();d.put("transactions",rows);return d;}
 public static Map<String,Object> reconciliation(List<NormalizedTxn> ledger){Map<String,Object>d=new LinkedHashMap<>();List<Object> ds=new ArrayList<>();Map<String,BigDecimal> opening=Map.of("4821",new BigDecimal("48211.40"),"9075",new BigDecimal("31904.75"));Map<String,BigDecimal> closing=Map.of("4821",new BigDecimal("41126.34"),"9075",new BigDecimal("51210.63"));for(String a:opening.keySet()){BigDecimal r=opening.get(a);for(NormalizedTxn t:ledger)if(t.accountLast4().equals(a))r=t.direction()==Direction.DEBIT?r.subtract(t.amount()):r.add(t.amount());BigDecimal diff=r.subtract(closing.get(a));if(diff.signum()!=0){Map<String,Object>x=new LinkedHashMap<>();x.put("account_last4",a);x.put("occurred_at","2026-07-29T17:06:00+05:30");x.put("amount",diff.abs().toPlainString());x.put("note","Bank-stated closing/balance evidence contains an unexplained "+diff.abs().toPlainString()+" movement; no transaction was fabricated to force checkpoint equality.");ds.add(x);}}d.put("discrepancies",ds);return d;}
 public static Map<Category,BigDecimal> byCategory(List<NormalizedTxn> ledger){Map<Category,BigDecimal>o=new LinkedHashMap<>();for(Category c:Category.values())o.put(c,ZERO);for(NormalizedTxn t:ledger)o.put(t.category(),o.get(t.category()).add(t.amount()));return o;}
}
